<?php
namespace Tests;
use App\Services\{SalonStore,Tenant,Contact,StaffAccess,ProviderPasswords};
use Carbon\CarbonImmutable as Time;
use Illuminate\Foundation\Testing\TestCase;
use Illuminate\Support\Facades\{Artisan,DB,Hash,Crypt,RateLimiter,Mail,Http};
final class TeamAccessTest extends TestCase{
 private string $path;
 public function createApplication(){$a=require __DIR__.'/../bootstrap/app.php';$a->make(\Illuminate\Contracts\Console\Kernel::class)->bootstrap();return $a;}
 protected function setUp():void{parent::setUp();if(config('database.default')!=='sqlite'&&!str_ends_with((string)config('database.connections.mysql.database'),'_test'))throw new \RuntimeException('Tesztadatbázis szükséges.');Artisan::call('migrate',['--force'=>true]);foreach(['provider_members','provider_password_tokens','provider_security','guest_auth_tokens','guest_credentials','guest_accounts','salon_state','providers','deliveries','calendar_tasks','calendar_connections','mail_templates'] as $t)DB::table($t)->delete();$s=SalonStore::initial();$s['settings']['businessMode']='team';$s['settings']['providerEmail']='owner@example.com';$s['settings']['billingTaxNumber']='PRIVATE-TAX';foreach([1,2] as $id)DB::table('salon_state')->insert(['id'=>$id,'data'=>json_encode($s)]);DB::table('providers')->insert(['id'=>2,'name'=>'Other Business','email'=>'other-owner@example.com','password_hash'=>Hash::make('Other-owner-password'),'active'=>true,'trial_started_at'=>now(),'trial_ends_at'=>now()->addYears(20),'created_at'=>now(),'updated_at'=>now()]);config(['raero.admin_password_hash'=>Hash::make('Owner-password-long')]);$this->path=storage_path('framework/team-'.bin2hex(random_bytes(5)));config(['integrations.path'=>$this->path,'operator.connections_path'=>$this->path.'-platform']);$this->withSession(['_token'=>str_repeat('m',40)])->withHeader('X-CSRF-TOKEN',str_repeat('m',40));Http::preventStrayRequests();}
 protected function tearDown():void{Time::setTestNow();foreach(['provider_members','provider_security','provider_password_tokens'] as $t)DB::table($t)->delete();foreach(glob($this->path.'*') as $p)unlink($p);parent::tearDown();}
 private function owner():void{$this->withSession(['admin'=>true,'provider_id'=>1,'provider_member_id'=>null,'provider_member_version'=>null,'provider_auth_method'=>'password','provider_password_version'=>1]);}
 private function out():void{$this->withSession(['admin'=>false,'guest_id'=>null,'provider_member_id'=>null,'provider_auth_method'=>null]);}
 private function member(string $role='editor',string $email='worker@example.com',string $staff='eszter'):array{$this->owner();return $this->postJson('/api/provider-members',['staff_id'=>$staff,'email'=>$email,'role'=>$role,'password'=>'Worker-password-long','password_confirmation'=>'Worker-password-long'])->assertCreated()->assertJsonMissingPath('password_hash')->json();}
 private function login(string $email='worker@example.com'):void{$this->out();$this->postJson('/api/provider-login',['email'=>$email,'password'=>'Worker-password-long'])->assertOk()->assertSessionHas('admin',true);$this->withHeader('X-CSRF-TOKEN',session('_token'));}
 private function booking(string $staff='eszter',string $start='2039-05-16T08:00:00Z'):array{return ['name'=>$staff==='eszter'?'Own guest':'Other guest','email'=>$staff==='eszter'?'own@example.com':'other@example.com','phone'=>$staff==='eszter'?'06301234567':'06209998888','staff'=>$staff,'services'=>[$staff==='eszter'?'massage':'cut'],'start'=>$start];}
 public function test_editor_only_receives_own_bookings_and_has_no_settings_financial_or_other_client_access():void{$m=$this->member();$own=$this->postJson('/api/bookings',$this->booking())->assertCreated()->json();$other=$this->postJson('/api/bookings',$this->booking('anna'))->assertCreated()->json();$this->login();$r=$this->getJson('/api/state')->assertOk()->assertJsonPath('_access.role','editor')->assertJsonCount(1,'bookings')->assertJsonPath('bookings.0.id',$own['id'])->assertJsonCount(1,'clients')->assertJsonCount(0,'payments');$this->assertStringNotContainsString('other@example.com',$r->getContent());$this->assertStringNotContainsString('PRIVATE-TAX',$r->getContent());$this->getJson('/api/clients/'.$other['clientId'].'/detail')->assertNotFound();$this->getJson('/api/clients/search?q=Other')->assertExactJson([]);foreach(['/api/provider-members','/api/connections','/api/subscription/info','/api/exports/statistics?from=2039-01-01&to=2039-12-31','/api/payments'] as $url)$this->getJson($url)->assertForbidden();$this->putJson('/api/config',['settings'=>['name'=>'Hijacked']])->assertForbidden();$this->patchJson('/api/bookings/'.$other['id'],['status'=>'cancelled'])->assertForbidden();$this->postJson('/api/bookings',$this->booking('anna','2039-05-17T08:00:00Z'))->assertForbidden();$this->getJson('/api/slots?date=2039-05-16&services=cut&staff=anna')->assertForbidden();$this->getJson('/api/state?provider=2')->assertForbidden();$this->patchJson('/api/bookings/'.$own['id'],['start'=>'2039-05-16T10:00:00Z'])->assertOk();$this->postJson('/api/bookings',$this->booking('eszter','2039-05-17T08:00:00Z'))->assertCreated();}
 public function test_member_admin_can_change_settings_but_revocation_and_demotion_take_effect_immediately():void{$m=$this->member('admin');$this->login();$s=app(SalonStore::class)->read();$this->putJson('/api/config',['settings'=>array_replace($s['settings'],['name'=>'New name'])])->assertOk();$this->getJson('/api/provider-members')->assertOk();$this->owner();$this->patchJson('/api/provider-members/'.$m['id'],['role'=>'editor'])->assertOk();$this->withSession(['admin'=>true,'provider_id'=>1,'provider_member_id'=>$m['id'],'provider_member_version'=>1]);$this->getJson('/api/state')->assertUnauthorized();$this->login();$this->getJson('/api/state')->assertJsonPath('_access.role','editor');$this->owner();$this->patchJson('/api/provider-members/'.$m['id'],['active'=>false])->assertOk();$this->out();$this->postJson('/api/provider-login',['email'=>'worker@example.com','password'=>'Worker-password-long'])->assertUnauthorized();}
 public function test_owner_and_editor_can_book_as_guest_without_losing_workplace_access():void{$this->member();$this->login();$guest=session('guest_id');$this->assertNotNull($guest);$this->getJson('/api/guest/billing')->assertOk();$this->postJson('/api/guest/invitations/claim')->assertOk()->assertJsonPath('claimed',false);$this->postJson('/api/bookings',$this->booking('anna')+['public'=>true])->assertCreated()->assertJsonPath('public',true)->assertJsonPath('guestId',$guest);$this->getJson('/api/guest')->assertOk()->assertJsonCount(1,'bookings');$this->getJson('/api/state')->assertJsonPath('_access.role','editor')->assertJsonCount(0,'bookings');$this->getJson('/api/slots?provider=2&public=1&date=2039-05-17&services=cut&staff=anna')->assertOk();$this->postJson('/api/quote?provider=2&public=1',['services'=>['cut']])->assertOk();$this->getJson('/api/calendar/connection?owner=guest&provider=2')->assertOk();$this->out();$this->postJson('/api/provider-login',['email'=>'owner@example.com','password'=>'Owner-password-long'])->assertOk();$ownerGuest=session('guest_id');$this->postJson('/api/bookings',$this->booking('anna','2039-05-17T08:00:00Z')+['public'=>true])->assertCreated()->assertJsonPath('guestId',$ownerGuest);$this->getJson('/api/state')->assertJsonPath('_access.owner',true);}
 public function test_guest_login_form_accepts_member_credentials_without_email_based_merging():void{$this->member();$existing=DB::table('guest_accounts')->insertGetId(['provider'=>'google','subject'=>'unrelated','name'=>'Different guest','email'=>'worker@example.com','created_at'=>now(),'updated_at'=>now()]);$this->out();$this->postJson('/api/guest/auth/login',['email'=>'worker@example.com','password'=>'Worker-password-long','returnTo'=>'booking'])->assertOk()->assertJsonPath('url','/foglalas?provider=1#public-form');$this->assertNotSame($existing,session('guest_id'));$this->getJson('/api/state')->assertJsonPath('_access.role','editor');}
 public function test_member_reset_and_password_change_never_change_the_owner_password():void{$m=$this->member();$ownerHash=ProviderPasswords::hash(1);$this->out();$this->postJson('/api/provider-password/forgot',['email'=>'worker@example.com'])->assertOk();$t=DB::table('provider_password_tokens')->first();$this->assertSame((int)$m['id'],(int)$t->member_id);$token=Crypt::decryptString($t->payload);$this->postJson('/api/provider-password/reset',['token'=>$token,'password'=>'Reset-worker-password','password_confirmation'=>'Reset-worker-password'])->assertOk();$this->postJson('/api/provider-password/reset',['token'=>$token,'password'=>'Reset-worker-password','password_confirmation'=>'Reset-worker-password'])->assertUnprocessable();$this->postJson('/api/provider-login',['email'=>'worker@example.com','password'=>'Reset-worker-password'])->assertOk();$this->postJson('/api/provider-password/change',['current_password'=>'wrong','password'=>'Changed-worker-password','password_confirmation'=>'Changed-worker-password'])->assertUnprocessable();$this->postJson('/api/provider-password/change',['current_password'=>'Reset-worker-password','password'=>'Changed-worker-password','password_confirmation'=>'Changed-worker-password'])->assertOk();$this->getJson('/api/state')->assertOk();$this->assertSame($ownerHash,ProviderPasswords::hash(1));}
 public function test_own_series_can_be_cancelled_but_other_series_cannot():void{$this->member();$other=$this->postJson('/api/bookings',$this->booking('anna')+['recurrence'=>['frequency'=>'weekly','count'=>2]])->assertCreated()->json();$this->login();$own=$this->postJson('/api/bookings',$this->booking()+['recurrence'=>['frequency'=>'weekly','count'=>2]])->assertCreated()->json();$this->postJson('/api/booking-series/'.$other['seriesId'].'/cancel')->assertForbidden();$this->postJson('/api/booking-series/'.$own['seriesId'].'/cancel')->assertOk()->assertJsonPath('cancelled',2);}
 public function test_multiple_workspaces_require_selecting_an_authenticated_membership():void{$first=$this->member();$row=DB::table('provider_members')->find($first['id']);$id=DB::table('provider_members')->insertGetId(['provider_id'=>2,'staff_id'=>'anna','email'=>$row->email,'password_hash'=>$row->password_hash,'role'=>'editor','created_at'=>now(),'updated_at'=>now()]);$this->out();$r=$this->postJson('/api/provider-login',['email'=>'worker@example.com','password'=>'Worker-password-long'])->assertOk()->assertJsonCount(2,'workspaces');$this->postJson('/api/provider-workspace',['memberId'=>9999])->assertForbidden();$this->postJson('/api/provider-workspace',['memberId'=>$id])->assertOk()->assertJsonPath('id',2);$this->getJson('/api/state?provider=2')->assertJsonPath('_access.staffId','anna');$this->getJson('/api/state?provider=1')->assertForbidden();}
 public function test_formatting_is_normalized_on_existing_records_and_unrepairable_numbers_are_rejected():void{foreach(['+36 30 123-4567','0036 (30) 123 4567','+36 (0) 30 123 4567','+36 06 30 1234567','30 123 4567',"06\u{00a0}30\u{2011}123\u{2011}4567"] as $v)$this->assertSame('06301234567',Contact::phone($v));$this->owner();app(SalonStore::class)->mutate(function(&$s){$s['clients'][]=['id'=>'old','name'=>'Old client','phone'=>'+36 (0)30 123-4567','email'=>''];});$this->postJson('/api/bookings',$this->booking()+['clientId'=>'old'])->assertCreated()->assertJsonPath('phone','06301234567');$this->assertSame('06301234567',app(SalonStore::class)->read()['clients'][0]['phone']);$this->postJson('/api/clients',['name'=>'Invalid','phone'=>'0630'])->assertUnprocessable();$this->postJson('/api/clients',['name'=>'Too long','phone'=>'063012345678888'])->assertUnprocessable();}
 public function test_custom_and_route_limits_report_the_actual_remaining_seconds():void{$key='login:127.0.0.1';RateLimiter::clear($key);for($i=0;$i<5;$i++)RateLimiter::hit($key,43);$r=$this->postJson('/api/login',['password'=>'wrong'])->assertStatus(429);$n=$r->json('retryAfter');$this->assertGreaterThan(0,$n);$this->assertLessThanOrEqual(43,$n);$r->assertHeader('Retry-After',(string)$n);$this->assertStringContainsString((string)$n,$r->json('error'));RateLimiter::clear($key);}
 public function test_framework_throttle_has_a_numeric_retry_message():void{for($i=0;$i<5;$i++)$this->postJson('/api/provider-login',['email'=>'missing@example.com','password'=>'wrong'])->assertUnauthorized();$r=$this->postJson('/api/provider-login',['email'=>'missing@example.com','password'=>'wrong'])->assertStatus(429);$n=$r->json('retryAfter');$this->assertGreaterThan(0,$n);$this->assertLessThanOrEqual(60,$n);$r->assertHeader('Retry-After',(string)$n);$this->assertStringContainsString((string)$n,$r->json('error'));}
 public function test_archiving_a_staff_member_revokes_their_session():void{$this->member();$this->login();app(SalonStore::class)->mutate(function(&$s){foreach($s['staff'] as &$p)if($p['id']==='eszter')$p['archived']=true;});$this->getJson('/api/state')->assertUnauthorized();}

 public function test_staff_and_login_are_created_atomically_and_invalid_password_leaves_no_staff():void{$this->owner();$before=count(app(SalonStore::class)->read()['staff']);$body=['email'=>'new-worker@example.com','role'=>'admin','password'=>'New-worker-password','password_confirmation'=>'wrong-password','newStaff'=>['name'=>'New Worker','role'=>'Trainer','phone'=>'+36 30 123-4567','description'=>'<p>Hello</p><script>alert(1)</script>']];$this->postJson('/api/provider-members',$body)->assertUnprocessable();$this->assertCount($before,app(SalonStore::class)->read()['staff']);$body['password_confirmation']=$body['password'];$m=$this->postJson('/api/provider-members',$body)->assertCreated()->assertJsonPath('role','admin')->json();$s=app(SalonStore::class)->read();$this->assertCount($before+1,$s['staff']);$person=collect($s['staff'])->firstWhere('id',$m['staff_id']);$this->assertSame('06301234567',$person['phone']);$this->assertStringNotContainsString('<script',$person['description']);$this->postJson('/api/provider-members',$body)->assertUnprocessable();$this->assertCount($before+1,app(SalonStore::class)->read()['staff']);$this->out();$this->postJson('/api/provider-login',['email'=>$body['email'],'password'=>$body['password']])->assertOk();$this->getJson('/api/state')->assertJsonPath('_access.role','admin');}

 public function test_unified_staff_profile_and_login_update_is_atomic():void{$m=$this->member();$before=collect(app(SalonStore::class)->read()['staff'])->firstWhere('id','eszter');$profile=['name'=>'Updated Worker','role'=>'Trainer','email'=>'contact@example.com','phone'=>'+36 30 123-4567','description'=>'<p>Hello</p><script>alert(1)</script>'];$this->patchJson('/api/provider-members/'.$m['id'],['email'=>'owner@example.com','staffProfile'=>$profile])->assertUnprocessable();$this->assertSame($before['name'],collect(app(SalonStore::class)->read()['staff'])->firstWhere('id','eszter')['name']);$this->patchJson('/api/provider-members/'.$m['id'],['email'=>'login-updated@example.com','role'=>'admin','staffProfile'=>$profile])->assertOk();$person=collect(app(SalonStore::class)->read()['staff'])->firstWhere('id','eszter');$this->assertSame('Updated Worker',$person['name']);$this->assertSame('login-updated@example.com',$person['email']);$this->assertSame('06301234567',$person['phone']);$this->assertStringNotContainsString('<script',$person['description']);$this->out();$this->postJson('/api/provider-login',['email'=>'login-updated@example.com','password'=>'Worker-password-long'])->assertOk();$this->getJson('/api/state')->assertJsonPath('_access.role','admin');}

 public function test_invitation_queues_one_use_password_setup_and_uses_one_email():void{$this->owner();$payload=['staff_id'=>'eszter','email'=>'invite@example.com','role'=>'editor','active'=>true,'sendInvitation'=>true,'staffProfile'=>['name'=>'Invited staff','role'=>'Trainer','email'=>'different@example.com','phone'=>'']];$m=$this->postJson('/api/provider-members',$payload)->assertCreated()->assertJsonPath('password_pending',1)->json();$this->assertSame('invite@example.com',collect(app(SalonStore::class)->read()['staff'])->firstWhere('id','eszter')['email']);$t=DB::table('provider_password_tokens')->where('member_id',$m['id'])->first();$this->assertSame('invite',$t->purpose);$this->assertGreaterThan(23*3600,strtotime($t->expires_at)-time());$token=Crypt::decryptString($t->payload);$this->out();$this->postJson('/api/provider-password/reset',['token'=>$token,'password'=>'Invited-password-long','password_confirmation'=>'Invited-password-long'])->assertOk();$this->assertFalse((bool)DB::table('provider_members')->where('id',$m['id'])->value('password_pending'));$this->postJson('/api/provider-password/reset',['token'=>$token,'password'=>'Invited-password-long','password_confirmation'=>'Invited-password-long'])->assertUnprocessable();$this->postJson('/api/provider-login',['email'=>'invite@example.com','password'=>'Invited-password-long'])->assertOk();}
 public function test_active_member_email_tracks_the_staff_profile_and_invalidates_old_tokens():void{$m=$this->member();ProviderPasswords::queue(1,(int)$m['id']);$this->patchJson('/api/staff/eszter',['name'=>'Worker','role'=>'Trainer','email'=>'single-email@example.com','phone'=>''])->assertOk();$this->assertSame('single-email@example.com',DB::table('provider_members')->where('id',$m['id'])->value('email'));$this->assertNotNull(DB::table('provider_password_tokens')->where('member_id',$m['id'])->value('used_at'));$this->out();$this->postJson('/api/provider-login',['email'=>'single-email@example.com','password'=>'Worker-password-long'])->assertOk();}

}
